import React, { useState } from "react";
import styled from "styled-components";
import FastaTable from "./Fasta";
import VirulenceTable from "./Virulence";
import AmrTable from "./Amr"; // Sửa lại import cho đúng tên component

const PopUpContainer = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const PopUpForm = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  width: 80%;
  max-height: 80%;
  overflow-y: auto;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px;
  right: 10px;
  background-color: transparent;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: #888;

  &:hover {
    color: #000;
  }
`;

const Container = styled.div`
  margin-top: 10px;
  display: flex;
  justify-content: center;
`;

const Wrapper = styled.div`
  width: 90%;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
`;

const Button = styled.button`
  padding: 15px 30px; /* Tăng kích thước nút */
  background-color: transparent;
  color: ${(props) => (props.selected ? "#007bff" : "#000")}; 
  border: 2px solid ${(props) => (props.selected ? "#007bff" : "#ccc")}; 
  border-radius: 5px;
  font-size: 18px; /* Tăng kích thước chữ */
  font-weight: ${(props) => (props.selected ? "bold" : "normal")}; 
  cursor: pointer;
  margin-right: 10px;

  &:hover {
    background-color: #f1f1f1;
  }

  &:last-child {
    margin-right: 0;
  }
`;

const Result = ({ fastaInfo, virulenceInfo, amrInfo, showModal, closeModal }) => {
  const [selectedTab, setSelectedTab] = useState("Fasta");

  const handleTabClick = (tab) => {
    setSelectedTab(tab);
  };

  if (!showModal) return null; // Không render nếu showModal là false

  return (
    <PopUpContainer>
      <PopUpForm>
        <CloseButton onClick={closeModal}>×</CloseButton>
        <Container>
          <Wrapper>
            <Title>Kết quả phân tích mẫu</Title>
            <ButtonGroup>
              <Button
                selected={selectedTab === "Fasta"}
                onClick={() => handleTabClick("Fasta")}
              >
                Fasta
              </Button>
              <Button
                selected={selectedTab === "Virulence"}
                onClick={() => handleTabClick("Virulence")}
              >
                Virulence
              </Button>
              <Button
                selected={selectedTab === "AMR"}
                onClick={() => handleTabClick("AMR")}
              >
                AMR
              </Button>
            </ButtonGroup>

            {selectedTab === "Fasta" && <FastaTable sample={fastaInfo} />}
            {selectedTab === "Virulence" && <VirulenceTable data={virulenceInfo} />}
            {selectedTab === "AMR" && <AmrTable data={amrInfo} />}
          </Wrapper>
        </Container>
      </PopUpForm>
    </PopUpContainer>
  );
};

export default Result;
